import java.util.*;
import java.util.function.*;

public class Sample001 {

    private int value = 10;
    private static int sValue = 20;

    class Inner {
        int value = 30;

        void print() {
            System.out.println(value);
            System.out.println(this.value);
            System.out.println(Sample001.this.value);
        }
    }

    static class Nested {
        static void show() {
            System.out.println(sValue);
        }
    }

    public static void main(String[] args) {

        Function<String,Integer> f1 = s -> s.length();

        Predicate<String> p1 = s -> s.startsWith("A");

        Consumer<String> c1 = System.out::println;

        Supplier<List<String>> sup = ArrayList::new;

        List<String> list = sup.get();
        list.add("Alpha");
        list.add("Beta");

        list.removeIf(s -> s.length() > 4);

        list.forEach(c1);

        Comparator<String> comp =
            Comparator.comparing(String::length)
                      .thenComparing(String::compareToIgnoreCase);

        list.sort(comp);

        Map<String,Integer> map = new HashMap<>();

        map.computeIfAbsent("A", k -> 100);

        System.out.println(map);

        new Sample001().new Inner().print();

        Nested.show();
    }
}

