    uses spi.Greeting;
}

// modx/module-info.java
module modx {
    exports foo;
    requires mody;
}

// mody/module-info.java
module mody {
    exports baz;
    provides spi.Greeting with provider.HelloGreeting;
}

// foo/Foo.java
package foo;

import baz.Baz;

public class Foo {

    public static void call() {
        System.out.println("Foo.call");
        Baz.show();
    }
}

// baz/Baz.java
package baz;

public class Baz {

    public static void show() {
        System.out.println("Baz.show");
    }
}

// Main.java
package app;

import foo.Foo;
import java.util.ServiceLoader;
import spi.Greeting;

public class Main {

    public static void main(String[] args) {

        Foo.call();

        ServiceLoader<Greeting> loader =
            ServiceLoader.load(Greeting.class);

        loader.stream()
              .map(ServiceLoader.Provider::get)
              .forEach(g -> System.out.println(g.hello()));
    }
}

