import java.text.*;
import java.util.*;

class Sample41 {
    public static void main(String[] args) throws Exception {
        LocalDate date = LocalDate.of(2025, 9, 30);

        DateTimeFormatter fmt =
            DateTimeFormatter.ofPattern(
                "Gy年MM月dd日 EEEE",
                Locale.JAPAN);

        System.out.println(date.format(fmt));

        JapaneseDate jp = JapaneseDate.from(date);
        System.out.println(jp);

        NumberFormat nf =
            NumberFormat.getCurrencyInstance(Locale.US);

        System.out.println(nf.format(1000.55));

        MessageFormat mf =
            new MessageFormat(
                "Hello {0}, date={1}",
                Locale.US);

        System.out.println(
            mf.format(new Object[]{"Duke", date}));
    }
}

